{
  "concepts": [
    {
      "conditions": [],
      "definition": "F15 describes release identification, publication, qualification, acceptance, selection and successor conservation. Its instance premises are recursive products, published point-in-time cuts available to uncontrolled consumers, movable shared carriers, source-matched derived assets, external services and predecessor-affecting successor lines. These premises are additional to the commitments. FOUNDATIONS owns the generic lineage taxonomy; this family traces and applies it without taking ownership.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 114,
          "quote": "Its instance premises, which the commitments do not supply, are",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F1.%20Context%20and%20position%2FFoundation%20to%20law%3A%20release%20and%20successor%20conservation",
          "start_line": 100
        }
      ],
      "key": "release_conservation_family",
      "label": "Release and successor conservation family"
    },
    {
      "conditions": [],
      "definition": "The lineage roles substrate, development product, source project, release cut, product, install, artifact and product definition are distinct identities with their own bases. A mutable workspace is not a fixed-identity product; an install acting as builder substrate is bound as a development product, without transferring meaning or authority to its authored product. A product definition is a source-project surface rather than the released artifact.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 118,
          "quote": "substrate, development product, source project, release cut, product, install, artifact and product definition are distinct objects.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F1.%20Context%20and%20position%2FFoundation%20to%20law%3A%20release%20and%20successor%20conservation",
          "start_line": 118
        }
      ],
      "key": "lineage_objects",
      "label": "Distinct product lineage objects"
    },
    {
      "conditions": [],
      "definition": "A stable repository-local key assigned by the Product release authority to one independently released source project.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 164,
          "quote": "- Project Release Namespace: a stable repository-local key assigned by\n  the Product release authority to one independently released source\n  project;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 162
        }
      ],
      "key": "project_release_namespace",
      "label": "Project Release Namespace"
    },
    {
      "conditions": [],
      "definition": "The exact repository-relative source-project root and Git tree object selected for a cut. The root is a locator within the peeled commit rather than Product identity.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 166,
          "quote": "- Project Subtree: the exact repository-relative source-project root and\n  Git tree object selected for one cut;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 165
        }
      ],
      "key": "project_subtree",
      "label": "Project Subtree"
    },
    {
      "conditions": [],
      "definition": "The mutable source-project state constructing a possible successor; its RC branch is a mutable project-qualified carrier for the current candidate window.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 170,
          "quote": "- Candidate Source: the candidate source of FOUNDATIONS §2, the mutable\n  source-project state constructing a possible successor;\n- RC Branch: a mutable project-qualified carrier for the current\n  candidate window;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 167
        }
      ],
      "key": "candidate_source",
      "label": "Candidate Source and RC branch"
    },
    {
      "conditions": [],
      "definition": "An annotated project-qualified Git tag together with its exact Product release subject. It names a published candidate and, once accepted, a released Product; it realises the generic release cut.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 173,
          "quote": "- Immutable RC Cut: an annotated project-qualified Git tag plus its exact\n  Product release subject (FOUNDATIONS §2), naming one published candidate\n  and, once accepted, one released Product; it realises the release cut;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 171
        }
      ],
      "key": "immutable_rc_cut",
      "label": "Immutable RC Cut"
    },
    {
      "conditions": [],
      "definition": "A mutable project-qualified tag alias naming the highest-ordinal published immutable RC cut for a project and version line. An optional, separately identified mutable release branch is a convenience carrier aligned to the selector's latest-published commit.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 179,
          "quote": "- Version-Line Selector: the mutable project-qualified tag alias naming\n  the highest-ordinal published immutable RC cut for that project and\n  version line; it realises the version-line selector of FOUNDATIONS §2;\n  and\n- Release Branch: an optional mutable project-qualified convenience\n  carrier aligned to the same latest-published commit as the selector.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 174
        }
      ],
      "key": "version_line_selector",
      "label": "Version-Line Selector and optional release branch"
    },
    {
      "conditions": [],
      "definition": "The declared exact Product member set or artifact, distinguished from its release-scoped claim surfaces and excluded co-located mutable source-project fields. Repository commits carry these sets without making all co-located files Product members.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 499,
          "quote": "- the exact Product member set or artifact constituting the release\n  subject;\n- the release-scoped claim surfaces describing that subject; and\n- co-located mutable source-project fields excluded from both.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F6.%20Release-scoped%20assets%20and%20the%20Product%20subject%2FProduct%20subject%20and%20repository%20carrier",
          "start_line": 496
        }
      ],
      "key": "product_release_subject",
      "label": "Product release subject"
    },
    {
      "conditions": [],
      "definition": "Optional cut-carried surfaces include release notes, release and installed-distribution manifests, dependency declarations, package or installed-carrier metadata, qualification receipts, and branch and tag identity declarations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 477,
          "quote": "- release notes;\n- release and installed-distribution manifests;\n- dependency declarations;\n- package or installed-carrier metadata;\n- qualification receipts; and\n- branch and tag identity declarations.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F6.%20Release-scoped%20assets%20and%20the%20Product%20subject%2FRelease-scoped%20assets",
          "start_line": 472
        }
      ],
      "key": "release_scoped_assets",
      "label": "Release-scoped assets"
    },
    {
      "conditions": [],
      "definition": "The represented release process has three phases: mutable candidate construction; immutable RC publication with monotonic version-line advancement; and exact-cut qualification, acceptance and explicit consumer adoption. A published cut provides one exact subject for review, replay and possible acceptance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 279,
          "quote": "1. mutable candidate construction;\n2. immutable RC publication and monotonic version-line advancement; and\n3. exact-cut qualification, acceptance and explicit consumer adoption.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F3.%20Phases",
          "start_line": 277
        }
      ],
      "key": "release_process",
      "label": "Release process"
    },
    {
      "conditions": [],
      "definition": "Qualification evaluates claims on an exact release subject, basis, observation boundaries and evidence, retaining owner verdicts, unresolved gaps and the complete successor relation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 347,
          "quote": "- each claimed property and its observation boundary;\n- evidence subjects, owner verdicts and unresolved gaps; and\n- the complete successor relation to the declared predecessor (§9).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F3.%20Phases%2FExact-cut%20qualification",
          "start_line": 345
        }
      ],
      "key": "exact_cut_qualification",
      "label": "Exact-cut qualification"
    },
    {
      "conditions": [],
      "definition": "The human Product authority's acceptance of an exact immutable RC identity after applicable mandatory gates. This is distinct from publication, selector advancement and consumer adoption.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 638,
          "quote": "- the human Product authority accepted the exact immutable RC identity.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F8.%20Acceptance%2FAcceptance%20criteria",
          "start_line": 638
        }
      ],
      "key": "release_acceptance",
      "label": "Release acceptance"
    },
    {
      "conditions": [],
      "definition": "An explicit Product-Definition transition that resolves, presents, installs, verifies and pins an immutable RC. Its externally presented read-only Adoption Plan binds the current definition bytes and basis to the exact target cut, tag object, peeled commit, tree and installed-manifest digest and emits a deterministic plan digest.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 409,
          "quote": "Adoption is a separate\nexplicit Product-Definition transition that resolves, presents, installs,\nverifies and pins the selected immutable RC.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F4.%20Selector%20and%20consumer%20adoption",
          "start_line": 407
        },
        {
          "end_line": 429,
          "quote": "the Adoption Plan of PRODUCT_DEFINITION §4, binds the current Product\nDefinition bytes and basis to the target immutable cut, annotated tag\nobject, peeled commit, tree and installed-manifest digest, then emits a\ndeterministic plan digest.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F4.%20Selector%20and%20consumer%20adoption",
          "start_line": 426
        }
      ],
      "key": "consumer_adoption",
      "label": "Consumer adoption and Adoption Plan"
    },
    {
      "conditions": [
        "A Product authority declares the relation because one corpus and its required distributed or derived assets need to remain usable as one versioned set."
      ],
      "definition": "An explicit cross-Product relation naming every required Product and asset, exact source dependency, owning authorities, qualification boundary and publication transaction. Co-location, equal versions and a common actor do not establish it.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 517,
          "quote": "The declaring\nrelation names every required Product and asset, the exact source\ndependency, its owning authorities, the qualification boundary and the\npublication transaction. Path co-location, equal version text or a common\nactor cannot infer the relation",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F7.%20Coordinated%20release-matched%20asset%20cohorts",
          "start_line": 513
        }
      ],
      "key": "release_matched_cohort",
      "label": "Release-Matched Asset Cohort"
    },
    {
      "conditions": [],
      "definition": "A successor's claim about one affecting predecessor claim: conserved means retained; superseded means replaced by an accepted successor relation; intentionally removed means removed by current Product authority; not applicable means no successor effect with a bounded reason. These are claim predicates, not evaluation result values or the decision owner's acceptance disposition. An unresolved disposition states no claim and has no result.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 678,
          "quote": "- conserved: the successor retains the claim;\n- superseded: an accepted successor relation replaces it;\n- intentionally removed: current Product authority removes it; or\n- not applicable: it has no successor effect, with a bounded reason.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F9.%20Successor%20baseline%20conservation%20%28STDO-UP-015%29",
          "start_line": 675
        },
        {
          "end_line": 716,
          "quote": "An unresolved disposition states no claim and so has no result: in the\nqualification of the affected claim it is a planned assessment without a\nclosed result",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F9.%20Successor%20baseline%20conservation%20%28STDO-UP-015%29",
          "start_line": 714
        }
      ],
      "key": "successor_disposition",
      "label": "Successor semantic disposition"
    },
    {
      "conditions": [],
      "definition": "A provenance table recording claimed conservation of rc.2 RELEASE_METHOD.md rows and their current loci. The table records restatement and changes of expression, not evaluated conservation or new rule authority. Generic release objects are defined in FOUNDATIONS and realised here.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 746,
          "quote": "Every conserved row is restated in this member's own\ntext; a route is provenance only.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/RELEASE.md#RELEASE%2F11.%20Source%20dispositions",
          "start_line": 745
        }
      ],
      "key": "release_source_disposition_record",
      "label": "RELEASE source-disposition record"
    },
    {
      "conditions": [],
      "definition": "Tier-2 owner of the particular spec-driven method: position and identity, constitutional chain, manifesto and litmus tests, requirement/design/trace/live-surface law, outcome conservation, change management and classification, consistency and sprint boundaries, ambiguity and lifecycle, lineage, migration, procedures, design records and build-tenant binding. It is realised from FOUNDATIONS, REFERENCE_FRAME, ACTIVATION and EVALUATION; its clauses are not foundational. PRODUCT_DEFINITION owns project binding, ASSURANCE testing law, TICKETS work carriers and RELEASE release mechanics.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 16,
          "quote": "nothing here is foundational, every clause\nnames the principle that requires it (P0 to P6, FOUNDATIONS §3), and each\nmechanism could be realised differently under the same principles.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD",
          "start_line": 14
        }
      ],
      "key": "spec_method",
      "label": "SPEC_METHOD"
    },
    {
      "conditions": [],
      "definition": "The meta-constitutional process for relating goals, intent, product, requirements, design, realisation, evidence and repricing, including sufficiency, requirement truth and authority flow. It aims to make software re-derivable, auditable and correctable under explicit authority. With surviving domain specification it should support rebuilding a project process after implementation loss.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 57,
          "quote": "the method should still be sufficient to bootstrap a new\nspec-driven project process from scratch; the method plus the surviving domain specification\ncan reconstruct the project",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FProcess%20constitution",
          "start_line": 55
        },
        {
          "end_line": 32,
          "quote": "Its point is to make software\nre-derivable, auditable and correctable under explicit authority.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FPosition",
          "start_line": 31
        }
      ],
      "key": "process_constitution",
      "label": "Process constitution"
    },
    {
      "conditions": [
        "Under the selected complete basis."
      ],
      "definition": "The bounded context urn:stdo:bounded-context:method-identity names STDO's four areas: Specification owned by SPEC_METHOD; Ticketing by TICKETS; Design by DESIGN_MODULE; and the complete Outcome-Driven Development area by ODD. This expansion neither makes those members independently selectable nor reduces the released Product to four members.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 103,
          "quote": "The expansion does not make the four owning\nmembers independently selectable and does not reduce the released product\nto four members: consumer authority remains one complete immutable released\ncut with its exact member inventory",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FMethod%20identity",
          "start_line": 100
        }
      ],
      "key": "stdo_method_identity",
      "label": "STDO method identity"
    },
    {
      "conditions": [],
      "definition": "The bounded work-wave surface naming current overriding concerns; more immediate than intent and higher-level than product definition and requirements. Temporary focus stays here until intentionally repriced into deeper layers.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 259,
          "quote": "The goals surface is the bounded work-wave surface: it captures the current\noverriding concerns for the next body of work, keeps temporary focus out of\ndeeper constitutional layers until it is intentionally repriced there, and\nis more immediate than intent while remaining higher-level than product\ndefinition and requirements.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 255
        }
      ],
      "key": "goals_surface",
      "label": "Goals"
    },
    {
      "conditions": [],
      "definition": "The surface of purpose, domain direction, and directional change that is in or out of scope.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 419,
          "quote": "Intent states why the\nsystem exists and what directional change is in or out of scope;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FSpecification%20surface%20rule",
          "start_line": 417
        }
      ],
      "key": "intent_surface",
      "label": "Intent"
    },
    {
      "conditions": [],
      "definition": "The mutable source project's current, present-tense product definition, key terms, boundaries and end-state shape, bridging direction to decomposable obligations. It is neither an immutable release cut nor an installed product. Its layout-neutral routing overlay locates actual authorities and tenant realisations without becoming rival constitutional truth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 265,
          "quote": "It is not the immutable release cut\nand not the installed product; those are the lineage objects of FOUNDATIONS\n§2",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 263
        },
        {
          "end_line": 116,
          "quote": "the definition is a routing\noverlay, not a rival truth surface",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FCanonical%20statement",
          "start_line": 115
        }
      ],
      "key": "product_definition_surface",
      "label": "Product Definition"
    },
    {
      "conditions": [],
      "definition": "The full constitutional WHAT: invariant truths, capabilities, constraints, guarantees, governance and verification obligations that the project must make true, with explicit acceptance criteria and enough information for downstream design derivation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 271,
          "quote": "Requirements are the constitutional what of the project. They are not\nlimited to user-visible features: the live requirement surface may include\ncapabilities, invariants, constraints, governance and verification\nobligations; what matters is that each requirement states something the\nproject must make true.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 267
        }
      ],
      "key": "requirements_surface",
      "label": "Requirements"
    },
    {
      "conditions": [],
      "definition": "The structural HOW: decisions, interfaces, topology, file placement, carrier documents, entry/control surfaces, runtime wiring and lawful tenant boundaries realising requirement truth. ADRs are durable design records, not a separate constitutional layer or requirement surface.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 228,
          "quote": "Design\ndefines the structural decisions, interfaces, carrier surfaces and delivery\ntopology that make those truths achievable; ADRs are one durable form of\ndesign record, not a second constitutional layer above design.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 225
        }
      ],
      "key": "design_surface",
      "label": "Design and design records"
    },
    {
      "conditions": [],
      "definition": "Realisation performs design decisions as code in software, human procedure in a human process, or both in a mixed environment. The tenant binding selects the carrier; the responsibilities called Code, Events and Projection do not themselves require a codebase or event store.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 231,
          "quote": "Code\nrealises those decisions where the selected execution environment is\nsoftware; a performed human procedure realises them where it is a human\nprocess, and both where it is mixed (§11).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 228
        }
      ],
      "key": "realisation",
      "label": "Code or other bound realisation"
    },
    {
      "conditions": [],
      "definition": "The owned homeostatic chain is Goals → Intent → Product Definition → Requirements → Design → Code → Events → Projection → Delta → Scenarios → Gap analysis → Repricing at the change-class layer. Events retain what happened in a selected stream, ledger, signed record or observation log; projection reconstructs current truth when that record suffices, without necessarily replaying a complete stream; delta reveals intended/realised drift; scenarios test operational meaning; gap analysis exposes insufficiency; repricing updates the appropriate layer.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 218,
          "quote": "Goals → Intent → Product Definition → Requirements → Design → Code\n  → Events → Projection → Delta → Scenarios → Gap analysis\n  → Repricing at the layer its change class names",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 216
        }
      ],
      "key": "constitutional_chain",
      "label": "Constitutional chain and homeostatic loop"
    },
    {
      "conditions": [],
      "definition": "Two independent requirement axes: category identifies Capability, Constraint / Guarantee, Governance or Verification truth; lifecycle status identifies Active, Deferred, Superseded or Orphaned standing. Capability supplies behaviour/function/surface; Constraint / Guarantee bounds behaviour through invariants or laws; Governance controls lifecycle, authority, visibility, release or operator action; Verification concerns tests, evidence, traceability, qualification or forensics.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 503,
